import{_ as r,a0 as p,w as i,s as a,ao as b,I as s,x as t,a1 as u,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"Ubuntu One 的10個鮮為人知的功能 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu One 的10個鮮為人知的功能 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu One 的10個鮮為人知的功能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu One 的10個鮮為人知的功能 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/10 Lesser Known Ubuntu One Features","title":"Ubuntu One 的10個鮮為人知的功能","tag":"201402","desc":""},"relativePath":"201402/10 Lesser Known Ubuntu One Features.md","filePath":"[post].md"}'),d={name:"201402/10 Lesser Known Ubuntu One Features.md"};function l(U,n,O,m,g,T){const e=p("Link");return i(),a("div",null,[n[11]||(n[11]=b('<h1 id="ubuntu-one-的10個鮮為人知的功能" tabindex="-1">Ubuntu One 的10個鮮為人知的功能 <a class="header-anchor" href="#ubuntu-one-的10個鮮為人知的功能" aria-label="Permalink to “Ubuntu One 的10個鮮為人知的功能”">​</a></h1><p>儘管 Ubuntu One 看上去像一個僅支持 Ubuntu 文件同步服務，但實際上它可以在 Windows，Android，iOS 和網頁上使用。而且，Ubuntu One 提供了5GB的免費存儲空間。</p><p><img src="http://www.efytimes.com/admin/useradmin/photo/Kj3S10756PM1212014.jpg" alt=""></p><p>根據 howtogeek.com 的介紹，用户通過 Ubuntu One 可以在線共享文件或目錄，推送音樂到手機，在所有的設備上同步已安裝的應用等等。下面我們一起來看一下10個Ubuntu One你也許不知道的功能。</p><p>1.<strong>同步目錄</strong> - 在默認設置下，Ubuntu 系統僅僅會同步用户主目錄下的 Ubuntu One 目錄。但是你可以用鼠標右擊任意文件夾，然後點擊 Ubuntu One 菜單，選擇 Synchronize This Folder 開始同步，這樣就可以將這個目錄加入到 Ubuntu One 中了。在 Ubuntu One 中，你可以管理所有的已同步目錄。</p><p>2.<strong>限制帶寬</strong> - 在默認設置下，Ubuntu One 會使用系統全部的網絡帶寬來上傳或下載文件。但是，如果你接入網絡速度比較慢，它也允許設定上傳和下載速度。你可以在 Ubuntu One 主窗口的設置界面裏找到帶寬設置。</p><p>3.<strong>在Windows上使用Ubuntu One</strong> - Ubuntu One 不是僅僅在 Linux 上運行，它也有一個 Windows 的客户端，提供完整的文件同步支持。Ubuntu One 是一個跨平台的文件同步服務，即使是完全沒有接觸過 Ubuntu 的 Windows 用户，也可以使用 Ubuntu One 提供的服務。</p><p>4.<strong>共享文件</strong> - 在文件管理器的鼠標右鍵菜單或者 Ubuntu One 網站，你可以將文件或者目錄共享到因特網上，也可以選擇分享給指定的 Ubuntu One 用户。</p><p>5.<strong>同步已安裝應用</strong> - Ubuntu One 可以在你所有的計算機上同步你從Ubuntu的軟件中心安裝的應用，這樣你就可以輕鬆管理已安裝的應用。</p><p>6.<strong>手機應用</strong> - Ubuntu One 為 Android，iPhone，iPad和Ipod Touch 提供了應用。通過這些應用，你可以在移動設備上輕鬆訪問 Ubuntu One 的文件。</p><p>7.<strong>自動上傳智能手機中的相片</strong> - 移動應用還支持自動上傳手機中的相片到 Ubuntu One 雲服務器中，這樣你可以輕鬆地在所有的設備上瀏覽你的相片。</p><p>8.<strong>在線音樂播放</strong> - Ubuntu One 還提供了 Ubuntu One 音樂應用，支持 Android和iOS。你可以通過智能手機在任意地方欣賞你的音樂，也可以選擇緩存到本地離線播放。</p><p>9.<strong>同步聯繫人</strong> - Ubuntu One可以同步你的聯繫人並在線保存。目前，你可以在 Ubuntu One 網頁上導入 Facebook 聯繫人，或者手動添加。早期版本的 Ubuntu 還支持同步 Evolution 郵件客户端的聯繫人，但在新的12.04版本中不支持從 Thunderbird 郵件客户端同步聯繫人。</p><p>10.<strong>在瀏覽器中管理你的文件</strong> - 在電腦上安裝了 Ubuntu One 後，可以在 Ubuntu One 網頁上管理本地文件。你可以在瀏覽器中下載文件，上傳文件，或者管理現有的文件。</p><hr>',15)),s("p",null,[n[1]||(n[1]=t("via: ",-1)),u(e,{href:"http://www.efytimes.com/e1/fullnews.asp?edid=127466"},{default:o(()=>[...n[0]||(n[0]=[t("http://www.efytimes.com/e1/fullnews.asp?edid=127466",-1)])]),_:1})]),s("p",null,[n[4]||(n[4]=t("譯者：",-1)),u(e,{href:"https://github.com/zpl1025"},{default:o(()=>[...n[2]||(n[2]=[t("zpl1025",-1)])]),_:1}),n[5]||(n[5]=t(" 校對：",-1)),u(e,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...n[3]||(n[3]=[t("Caroline",-1)])]),_:1})]),s("p",null,[n[8]||(n[8]=t("本文由 ",-1)),u(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[6]||(n[6]=[t("LCTT",-1)])]),_:1}),n[9]||(n[9]=t(" 原創翻譯，",-1)),u(e,{href:"http://linux.cn/"},{default:o(()=>[...n[7]||(n[7]=[t("Linux中國",-1)])]),_:1}),n[10]||(n[10]=t(" 榮譽推出",-1))])])}const L=r(d,[["render",l]]);export{C as __pageData,L as default};
